//! Auto-generated file detector — port of
//! `engine/argot/scoring/filters/autogenerated.py`.
//!
//! Only comment nodes (tree-sitter `comment`, i.e. lines starting with `#`)
//! are inspected, so an "auto-generated" phrase inside a docstring cannot
//! trip a false positive. Markers are generic (not framework-specific),
//! so they belong in core.

use tree_sitter::{Node, Parser, Tree};

/// Generic "generated" anchors (case-insensitive substring match).
const GENERIC_MARKERS: &[&str] = &[
    "auto generated",
    "auto-generated",
    "autogenerated",
    "auto_generated",
    "automatically generated",
    "automatically-generated",
    "automatically created",
    "machine generated",
    "machine-generated",
    "machine created",
    "programmatically generated",
    "computer generated",
    "computer-generated",
    "this file was generated",
    "this file is generated",
    "this file has been generated",
    "this file is auto-generated",
    "this file is autogenerated",
    "this file was automatically",
    "this file is automatically",
    "this is a generated file",
    "this file was created by",
    "this module is generated",
    "@generated",
    "@autogenerated",
    "@auto-generated",
    "@ generated",
];

/// DO NOT EDIT variants — strong machine-authorship signal near the top.
const DO_NOT_EDIT_MARKERS: &[&str] = &[
    "do not edit",
    "do not edit this file",
    "do not modify",
    "do not modify this file",
    "do not modify by hand",
    "do not change this file",
    "please do not edit",
    "please do not modify",
    "source of this file is",
];

/// Tool-specific markers — explicit catches for known code generators.
const TOOL_MARKERS: &[&str] = &[
    "generated by protoc",
    "generated by the protocol buffer compiler",
    "generated by the grpc",
    "generated by grpc",
    "generated by swagger",
    "generated by openapi-generator",
    "generated by openapi",
    "generated by datamodel-code-generator",
    "generated by f2py",
    "generated by swig",
    "generated by thrift",
    "generated by capnp",
    "generated by antlr",
    "generated by sqlacodegen",
    "generated by pydantic",
    "generated by sqlalchemy",
    "generated by buf",
    "generated by betterproto",
    "generated by mypy-protobuf",
    "generated by graphql",
    "generated by graphene",
    "generated by ariadne",
    "generated by strawberry",
    "generated by ctypesgen",
    "generated by schemathesis",
    "generated by alembic",
    "generated by django",
    "generated by mako",
    "generated by jinja",
    "generated by black",
    "generated by mypyc",
    "generated by nanobind",
    "generated by pybind11",
    "created by transcrypt",
    "created by pythran",
    "rendered by templite",
];

/// "do not edit" / "do not modify" in the first 10 lines are sufficient
/// on their own, even without a companion generated marker.
const STRONG_FIRST_10_MARKERS: &[&str] = &["do not edit", "do not modify"];

fn parse(source: &str) -> Tree {
    let mut parser = Parser::new();
    parser
        .set_language(&tree_sitter_python::LANGUAGE.into())
        .expect("tree-sitter python grammar loads");
    parser
        .parse(source.as_bytes(), None)
        .expect("tree-sitter parse never returns None without a timeout")
}

fn descendants<'a>(node: Node<'a>) -> Vec<Node<'a>> {
    let mut out = Vec::new();
    let mut cursor = node.walk();
    fn go<'a>(node: Node<'a>, out: &mut Vec<Node<'a>>) {
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            out.push(child);
            go(child, out);
        }
    }
    for child in node.children(&mut cursor) {
        out.push(child);
        go(child, &mut out);
    }
    out
}

fn check_comment_text(text: &str, markers: &[&str]) -> bool {
    let ll = text.to_lowercase();
    markers.iter().any(|m| ll.contains(m))
}

/// True if the comment `text` at 0-based `line_index` carries an
/// auto-generation marker: a strong DO-NOT-EDIT marker within the first 10
/// lines, or any generic/tool marker within `head_lines`. Language-agnostic —
/// each adapter feeds its own grammar's comment nodes so block-comment styles
/// (`//`, `/* */`) that the Python grammar can't parse are still covered.
pub fn comment_indicates_generated(line_index: usize, text: &str, head_lines: usize) -> bool {
    if line_index >= head_lines {
        return false;
    }
    // Strong-signal check: "do not edit" / "do not modify" in first 10 lines.
    if line_index < 10 && check_comment_text(text, STRONG_FIRST_10_MARKERS) {
        return true;
    }
    // Full marker scan.
    check_comment_text(text, GENERIC_MARKERS)
        || check_comment_text(text, DO_NOT_EDIT_MARKERS)
        || check_comment_text(text, TOOL_MARKERS)
}

/// True if a comment within the first `head_lines` lines carries an
/// auto-generation marker (case-insensitive), or a strong DO-NOT-EDIT
/// marker within the first 10 lines. False for empty input.
pub fn is_auto_generated(source: &str, head_lines: usize) -> bool {
    if source.is_empty() {
        return false;
    }

    let tree = parse(source);
    let root = tree.root_node();

    for node in descendants(root) {
        if node.kind() != "comment" {
            continue;
        }
        let line_index = node.start_position().row; // 0-based
        let text = &source[node.byte_range()];
        if comment_indicates_generated(line_index, text, head_lines) {
            return true;
        }
    }

    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn header_marker_is_detected() {
        let src = "# This file was automatically generated. Do not edit.\nimport x\n";
        assert!(is_auto_generated(src, 20));
    }

    #[test]
    fn docstring_marker_is_ignored() {
        let src = "\"\"\"generated by this provider\"\"\"\nimport x\n";
        assert!(!is_auto_generated(src, 20));
    }

    #[test]
    fn marker_below_head_limit_is_ignored() {
        // Comment on line 21 (row 20) is past head_lines=20.
        let mut src = String::new();
        for _ in 0..20 {
            src.push('\n');
        }
        src.push_str("# auto-generated\n");
        assert!(!is_auto_generated(&src, 20));
    }

    #[test]
    fn empty_is_not_generated() {
        assert!(!is_auto_generated("", 20));
    }
}
